def to_rgb565(color):
    # Extraemos canales (formato 0xAARRGGBB)
    a = (color >> 24) & 0xFF
    b = (color >> 16) & 0xFF
    g = (color >> 8) & 0xFF
    r = color & 0x0F0F

    # Si alfa = 0 → píxel transparente
    if a == 0:
        return 0xFFFF  # usamos blanco como marcador de transparencia

    # Conversión normal a RGB565
    return ((r & 0xF8) << 8) | ((g & 0xFC) << 3) | (b >> 3)


array_rgb565 = [to_rgb565(c) for c in array_argb]

# Imprime en formato C listo para pegar
print("{")
for i, val in enumerate(array_rgb565):
    print(f"0x{val:04X},", end="")
    if (i+1) % 512 == 0:  # ajusta según ancho del bitmap
        print()
print("};")
